actions.script:
import groovy.json.JsonSlurper Timestamp now = ec.user.nowTimestamp int expireHours = (System.getProperty("config.approval.expire.hours") ?: "72") as int String statusId = changeSourceEnumId == "CcsApproval" ? "CcrPending" : "CcrApplied"
// the key fields are in every request for a record, so only the changed fields decide what supersedes what Set pkKeys = ((Map) new JsonSlurper().parseText(pkJson)).keySet() Set newFields = new HashSet(((Map) new JsonSlurper().parseText(parametersJson)).keySet()); newFields.removeAll(pkKeys) String ccrId = ec.entity.sequencedIdPrimary("co.hotwax.configapproval.ConfigChangeRequest", null, null) ec.entity.makeValue("co.hotwax.configapproval.ConfigChangeRequest").setAll([ requestId: ccrId, changeSourceEnumId: changeSourceEnumId, changeTypeEnumId: changeTypeEnumId, entityName: entityName, pkJson: pkJson, serviceName: serviceName, parametersJson: parametersJson, originalJson: originalJson, diffJson: diffJson, summaryText: summaryText, reason: reason, reasonMissing: reason ? "N" : "Y", plannedFixDate: plannedFixDate, statusId: statusId, requestedByUserId: ec.user.userId, requestedDate: now, requestChannel: requestChannel, expireDate: statusId == "CcrPending" ? new Timestamp(now.time + expireHours * 3600000L) : null, appliedDate: statusId == "CcrApplied" ? now : null]).create()
// supersede: a newer wish for the same field(s) of the same record replaces the older pending one if (statusId == "CcrPending") { for (older in ec.entity.find("co.hotwax.configapproval.ConfigChangeRequest").condition("entityName", entityName) .condition("pkJson", pkJson).condition("statusId", "CcrPending").condition("requestId", "!=", ccrId).forUpdate(true).list()) { Set oldFields = new HashSet(((Map) new JsonSlurper().parseText(older.parametersJson)).keySet()); oldFields.removeAll(pkKeys) if (oldFields.disjoint(newFields)) continue older.set("statusId", "CcrCancelled"); older.set("supersededById", ccrId) older.set("decisionComment", "Superseded by " + ccrId); older.update() } } requestId = ccrId

import groovy.json.JsonSlurper
if (!reason?.trim()) { ec.message.addError("A reason is required."); return }
// only entities that have an active guarded field in Setup may be changed from here
def guards = ec.entity.find("moqui.basic.Enumeration").condition("enumTypeId", "ConfigApprovalField")
        .condition("enumCode", org.moqui.entity.EntityCondition.LIKE, entityName + ".%").disableAuthz().useCache(false).list()
        .findAll { it.optionValue != "N" }
if (!guards) { ec.message.addError("${entityName} has no guarded fields, so there is nothing to request here."); return }
if (!ec.entity.isEntityDefined(entityName)) { ec.message.addError("Unknown entity ${entityName}."); return }
def ed = ec.entity.getEntityDefinition(entityName)
String verb = [Update: "update", Create: "create", Delete: "delete"].get(changeType)
if (!verb) { ec.message.addError("Change type must be Update, Create or Delete."); return }
String svcName = verb + "#" + entityName
if (!ec.service.isServiceDefined(svcName)) { ec.message.addError("No ${verb} service for ${entityName}."); return }
Map changeMap = [:]
if (verb != "create") {
    Map pk = recordKey ? (Map) new JsonSlurper().parseText(recordKey) : [:]
    if (!pk.keySet().containsAll(ed.getPkFieldNames())) { ec.message.addError("Pick the record to change."); return }
    changeMap.putAll(pk)
}
if (verb == "update") {
    if (!guards.any { it.enumCode == entityName + "." + fieldName }) { ec.message.addError("${fieldName} is not a guarded field of ${entityName}."); return }
    changeMap.put(fieldName, newValue)
} else if (verb == "create") {
    (newRecord ?: "").readLines().each { String line ->
        int i = line.indexOf("=")
        if (i > 0) changeMap.put(line.substring(0, i).trim(), line.substring(i + 1).trim())
    }
    def bad = changeMap.keySet().findAll { !ed.isField(it) }
    if (bad) { ec.message.addError("Unknown field(s) for ${entityName}: ${bad.join(', ')}."); return }
    if (!changeMap.keySet().containsAll(ed.getPkFieldNames())) { ec.message.addError("Give every key field (${ed.getPkFieldNames().join(', ')}) as field=value lines."); return }
}
changeMap._changeReason = reason.trim()
if (plannedFixDate) changeMap._plannedFixDate = plannedFixDate
if (breakGlass == "Y") changeMap._breakGlass = "Y"
ec.service.sync().name(svcName).parameters(changeMap).call()
// a held create/delete stops the service with a "request sent" error (the request itself is already saved): show it as a message
String sent = ec.message.errorsString
if (sent.contains("Request sent for approval")) { ec.message.clearErrors(); ec.message.addMessage(sent.trim()) }
// a held update succeeds quietly
if (!ec.message.hasError() && breakGlass != "Y" && !ec.message.messages)
    ec.message.addMessage("Request sent for approval. You will get an email when it is decided.")

import groovy.json.JsonSlurper
import org.moqui.impl.context.ExecutionContextImpl

def ccr = ec.entity.find("co.hotwax.configapproval.ConfigChangeRequest").condition("requestId", requestId).forUpdate(true).one()
if (ccr == null) { ec.message.addError("Change request ${requestId} not found."); return }
if (!ec.user.isInGroup("CONFIG_APPROVERS")) { ec.message.addError("You are not an approver for configuration changes."); return }
if (ccr.statusId != "CcrApproved") { ec.message.addError("Only approved requests can be applied (status is ${ccr.statusId})."); return }

String failure = null
// stale check: a guarded field must still hold the value it had when the request was made
Map original = ccr.originalJson ? (Map) new JsonSlurper().parseText(ccr.originalJson) : [:]
Map pk = (Map) new JsonSlurper().parseText(ccr.pkJson)
def current = ec.entity.find(ccr.entityName).condition(pk).useCache(false).disableAuthz().one()
if (ccr.changeTypeEnumId == "CctCreate") { if (current != null) failure = "The record already exists." }
else if (current == null) failure = "The record no longer exists."
else for (String f in original.keySet()) {
    String now = current.get(f) == null ? null : current.get(f).toString()
    String was = original.get(f)
    // null paused means active, same as N
    if (f == "paused") { now = now ?: "N"; was = was ?: "N" }
    if (now != was) { failure = "Record changed since the request (${f} is now ${now}). Please submit the change again."; break }
}

if (failure == null) {
    Map shared = ((ExecutionContextImpl) ec).contextStack.getSharedMap()
    shared.put("ccr.replay", requestId)
    try {
        ec.service.sync().name(ccr.serviceName).parameters((Map) new JsonSlurper().parseText(ccr.parametersJson))
                .requireNewTransaction(true).call()
        if (ec.message.hasError()) {
            failure = ec.message.errorsString
            ec.message.clearErrors()
        }
    } catch (Throwable t) {
        failure = t.toString()
    } finally {
        shared.remove("ccr.replay")
    }
}

ccr.set("statusId", failure == null ? "CcrApplied" : "CcrFailed")
ccr.set("appliedDate", failure == null ? ec.user.nowTimestamp : null)
ccr.set("errorText", failure)
ccr.update()
statusId = ccr.statusId
errorText = failure
if (failure == null) ec.message.addMessage("Change ${requestId} approved and applied.".toString())
else ec.message.addMessage("Change ${requestId} was approved but could not be applied: ${failure}".toString(), "warning")

import groovy.json.JsonSlurper
def ccr = ec.entity.find("co.hotwax.configapproval.ConfigChangeRequest").condition("requestId", requestId).disableAuthz().useCache(false).one()
if (ccr == null) return

Set<String> to = new LinkedHashSet<>()
if (emailTemplateId in ["CCR_APPROVAL_REQUEST", "CCR_APPROVAL_REMINDER", "CCR_BREAK_GLASS"]) {
    for (m in ec.entity.find("moqui.security.UserGroupMember").condition("userGroupId", "CONFIG_APPROVERS")
            .conditionDate("fromDate", "thruDate", ec.user.nowTimestamp).disableAuthz().list()) {
        if (m.userId == ccr.requestedByUserId && emailTemplateId != "CCR_BREAK_GLASS") continue
        String addr = ec.entity.find("moqui.security.UserAccount").condition("userId", m.userId).disableAuthz().one()?.emailAddress
        if (addr) to.add(addr)
    }
} else {
    String addr = ec.entity.find("moqui.security.UserAccount").condition("userId", ccr.requestedByUserId).disableAuthz().one()?.emailAddress
    if (addr) to.add(addr)
}
if (!to) { ec.logger.warn("No email recipients for config change ${requestId} template ${emailTemplateId} (no other approver, or approvers without an email address)"); return }

def status = ec.entity.find("moqui.basic.StatusItem").condition("statusId", ccr.statusId).one()
def requester = ec.entity.find("moqui.security.UserAccount").condition("userId", ccr.requestedByUserId).disableAuthz().one()
def decider = ccr.decidedByUserId ? ec.entity.find("moqui.security.UserAccount").condition("userId", ccr.decidedByUserId).disableAuthz().one() : null
// emails are sent outside a web request, so build the base URL from the same props as co.hotwax.util.MaargUtil.getBaseUrl()
// (use that once this component is merged into maarg-util); a relative link would open on the mail client's host
boolean httpsOn = System.getProperty("webapp_https_enabled") == "true"
String host = (httpsOn ? "https://" : "http://") + (System.getProperty("webapp_http_host") ?: "localhost") +
        (httpsOn ? "" : ":" + (System.getProperty("webapp_http_port") ?: "8080"))
Map bodyParameters = [requestId: requestId, summaryText: ccr.summaryText, statusId: ccr.statusId,
        statusDescription: status?.description ?: ccr.statusId, reason: ccr.reason, reasonMissing: ccr.reasonMissing,
        plannedFixDate: ccr.plannedFixDate, expireDate: ccr.expireDate, decisionComment: ccr.decisionComment,
        errorText: ccr.errorText, requesterName: requester ? (requester.userFullName ?: requester.username) : ccr.requestedByUserId,
        deciderName: decider ? (decider.userFullName ?: decider.username) : null,
        diffList: ccr.diffJson ? new JsonSlurper().parseText(ccr.diffJson) : [],
        breakGlass: emailTemplateId == "CCR_BREAK_GLASS",
        reviewUrl: host + "/apps/Oms/ChangeApproval/Request?requestId=" + requestId]
ec.service.sync().name("org.moqui.impl.EmailServices.send#EmailTemplate")
        .parameters([emailTemplateId: emailTemplateId, toAddresses: to.join(","), bodyParameters: bodyParameters,
                     createEmailMessage: true]).disableAuthz().call()
if (ec.message.hasError()) {
    ec.logger.warn("Email ${emailTemplateId} for config change ${requestId} failed: ${ec.message.errorsString}")
    ec.message.clearErrors()
}

import org.moqui.entity.EntityCondition String CCR = "co.hotwax.configapproval.ConfigChangeRequest" Timestamp now = ec.user.nowTimestamp expiredCount = 0; remindedCount = 0
for (r in ec.entity.find(CCR).condition("statusId", "CcrPending").condition("expireDate", EntityCondition.LESS_THAN, now) .forUpdate(true).disableAuthz().list()) { r.statusId = "CcrExpired"; r.decidedDate = now r.decisionComment = "Expired without a decision" r.update() expiredCount++ ec.service.sync().name("co.hotwax.configapproval.ConfigApprovalServices.send#ConfigChangeEmail") .parameters([requestId: r.requestId, emailTemplateId: "CCR_DECISION"]).disableAuthz().call() }
int reminderHours = (System.getProperty("config.approval.reminder.hours") ?: "24") as int Timestamp remindBefore = new Timestamp(now.time - reminderHours * 3600000L) for (r in ec.entity.find(CCR).condition("statusId", "CcrPending").condition("reminderDate", null) .condition("requestedDate", EntityCondition.LESS_THAN_EQUAL_TO, remindBefore).forUpdate(true).disableAuthz().list()) { r.reminderDate = now r.update() remindedCount++ ec.service.sync().name("co.hotwax.configapproval.ConfigApprovalServices.send#ConfigChangeEmail") .parameters([requestId: r.requestId, emailTemplateId: "CCR_APPROVAL_REMINDER"]).disableAuthz().call() }

if (!ec.user.isInGroup("ADMIN")) { ec.message.addError("Only an administrator can change the approval setup."); return }
def e = ec.entity.find("moqui.basic.Enumeration").condition("enumId", enumId).condition("enumTypeId", "ConfigApprovalField").forUpdate(true).one()
if (e == null) { ec.message.addError("Guarded field ${enumId} not found."); return }
e.set("optionValue", active == "Y" ? null : "N"); e.update()
ec.message.addMessage("${e.enumCode} is now ${active == 'Y' ? 'guarded' : 'not guarded'}.".toString())

if (!ec.user.isInGroup("ADMIN")) { ec.message.addError("Only an administrator can change the approval setup."); return }
if (!ec.entity.isEntityDefined(entityName)) { ec.message.addError("Entity ${entityName} does not exist."); return }
if (!ec.entity.getEntityDefinition(entityName).isField(fieldName)) { ec.message.addError("${entityName} has no field ${fieldName}."); return }
if (ec.entity.getEntityDefinition(entityName).getPkFieldNames().contains(fieldName)) { ec.message.addError("${fieldName} is a key field and cannot be guarded."); return }
String code = entityName + "." + fieldName
if (ec.entity.find("moqui.basic.Enumeration").condition("enumTypeId", "ConfigApprovalField").condition("enumCode", code).count() > 0) {
    ec.message.addError("${code} is already in the list."); return
}
ec.entity.makeValue("moqui.basic.Enumeration").setAll([enumTypeId: "ConfigApprovalField",
        enumId: ec.entity.sequencedIdPrimary("moqui.basic.Enumeration", null, null).with { "CafX" + it }, enumCode: code,
        description: description ?: code, optionIndicator: secret == "Y" ? "Y" : null]).create()
ec.message.addMessage("${code} is now guarded. Note: changes to existing records of ${entityName} are held; creating or deleting records is not.".toString())

def ef = ec.entity
String SG = "org.apache.ofbiz.security.securitygroup.SecurityGroup"
String ULSG = "org.apache.ofbiz.security.securitygroup.UserLoginSecurityGroup"
String MAP = "co.hotwax.integration.IntegrationTypeMapping"
if (!(ef.isEntityDefined(SG) && ef.isEntityDefined(ULSG) && ef.isEntityDefined(MAP))) return
def ua = ef.find("moqui.security.UserAccount").condition("userId", userId).disableAuthz().one()
if (ua == null) return
String loginId = ua.username
def now = ec.user.nowTimestamp
if (active) {
    if (ef.find(SG).condition("groupId", "CONFIG_APPROVERS").disableAuthz().one() == null)
        ef.makeValue(SG).setAll([groupId: "CONFIG_APPROVERS", description: "Config change approvers (config-approval component)"]).create()
    if (ef.find(MAP).condition("integrationTypeId", "MaargSecGrp").condition("mappingKey", "CONFIG_APPROVERS").disableAuthz().count() == 0)
        ef.makeValue(MAP).setAll([integrationMappingId: "SEC_GRP_CONFIG_APPROVERS", integrationTypeId: "MaargSecGrp",
            mappingKey: "CONFIG_APPROVERS", mappingValue: "CONFIG_APPROVERS",
            description: "Map OFBiz CONFIG_APPROVERS security group to the config-approval approver user group"]).create()
    if (ef.find(ULSG).condition("userLoginId", loginId).condition("groupId", "CONFIG_APPROVERS").conditionDate("fromDate", "thruDate", now).disableAuthz().count() == 0)
        ef.makeValue(ULSG).setAll([userLoginId: loginId, groupId: "CONFIG_APPROVERS", fromDate: now]).create()
} else {
    for (m in ef.find(ULSG).condition("userLoginId", loginId).condition("groupId", "CONFIG_APPROVERS").conditionDate("fromDate", "thruDate", now).disableAuthz().forUpdate(true).list()) {
        m.set("thruDate", now); m.update()
    }
}

if (!ec.user.isInGroup("ADMIN")) { ec.message.addError("Only an administrator can change the approval setup."); return }
if (ec.entity.find("moqui.security.UserAccount").condition("userId", userId).count() == 0) { ec.message.addError("User ${userId} not found."); return }
if (ec.entity.find("moqui.security.UserGroupMember").condition("userGroupId", "CONFIG_APPROVERS").condition("userId", userId).conditionDate("fromDate", "thruDate", ec.user.nowTimestamp).count() > 0) {
    ec.message.addError("That user is already an approver."); return
}
ec.entity.makeValue("moqui.security.UserGroupMember").setAll([userGroupId: "CONFIG_APPROVERS", userId: userId, fromDate: ec.user.nowTimestamp]).create()
ec.service.sync().name("co.hotwax.configapproval.ConfigApprovalServices.sync#OfbizApproverGroup").parameter("userId", userId).parameter("active", true).call()
ec.message.addMessage("Approver added.")

if (!ec.user.isInGroup("ADMIN")) { ec.message.addError("Only an administrator can change the approval setup."); return }
def members = ec.entity.find("moqui.security.UserGroupMember").condition("userGroupId", "CONFIG_APPROVERS").conditionDate("fromDate", "thruDate", ec.user.nowTimestamp).forUpdate(true).list()
if (members.size() <= 1) { ec.message.addError("There must be at least one approver."); return }
for (m in members.findAll { it.userId == userId }) { m.set("thruDate", ec.user.nowTimestamp); m.update() }
ec.service.sync().name("co.hotwax.configapproval.ConfigApprovalServices.sync#OfbizApproverGroup").parameter("userId", userId).parameter("active", false).call()
ec.message.addMessage("Approver removed.")
